import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64
.visible .entry sigmoid_forward(
    .param .u64 input_ptr,
    .param .u64 output_ptr,
    .param .u32 n_elts
)
{
    .reg .pred  %p1;
    .reg .b32   %r_tid, %r_ntid, %r_ctaid, %r_idx, %r_n, %r_nctaid, %r_stride, %r_i;
    .reg .b64   %in, %out, %addr_in, %addr_out, %offset;
    .reg .f32   %x, %negx, %w, %expv, %one, %denom, %res;
    // Load parameters
    ld.param.u64  %in,  [input_ptr];
    ld.param.u64  %out, [output_ptr];
    ld.param.u32  %r_n, [n_elts];
    // Convert to global addresses
    cvta.to.global.u64 %in, %in;
    cvta.to.global.u64 %out, %out;
    // Compute linear thread index
    mov.u32 %r_tid,   %tid.x;
    mov.u32 %r_ntid,  %ntid.x;
    mov.u32 %r_ctaid, %ctaid.x;
    mad.lo.u32 %r_idx, %r_ctaid, %r_ntid, %r_tid;
    // Compute grid stride = blockDim.x * gridDim.x
    mov.u32 %r_nctaid, %nctaid.x;
    mul.lo.u32 %r_stride, %r_ntid, %r_nctaid;
    // Initialize loop index
    mov.u32 %r_i, %r_idx;
LOOP:
    // Bounds check for current i
    setp.ge.u32 %p1, %r_i, %r_n;
    @%p1 bra DONE;
    // Byte offset = i * sizeof(float)
    mul.wide.u32 %offset, %r_i, 4;
    add.s64 %addr_in,  %in,  %offset;
    add.s64 %addr_out, %out, %offset;
    // Load input
    ld.global.f32 %x, [%addr_in];
    // Sigmoid: 1 / (1 + exp(-x))
    neg.f32 %negx, %x;
    // w = -x * log2(e) with log2(e) = 1.442695 (0x3fb8aa3b)
    mul.f32 %w, %negx, 0f3fb8aa3b;
    // exp(-x) = 2^(w)
    ex2.approx.f32 %expv, %w;
    // denom = 1.0f + exp(-x)
    mov.b32 %one, 0x3f800000; // 1.0f
    add.f32 %denom, %expv, %one;
    // result = 1.0f / denom
    div.rn.f32 %res, %one, %denom;
    // Store output
    st.global.f32 [%addr_out], %res;
    // Next element for this thread
    add.u32 %r_i, %r_i, %r_stride;
    bra LOOP;
DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("sigmoid_forward")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            raise RuntimeError("ModelNew requires CUDA tensors.")
        if x.dtype != torch.float32:
            raise RuntimeError("ModelNew expects float32 input dtype.")
        if not x.is_contiguous():
            raise RuntimeError("ModelNew expects contiguous input tensor.")

        out = torch.empty_like(x)
        n = x.numel()
        if n == 0:
            return out

        threads = 256
        grid_x = min((n + threads - 1) // threads, 65535)

        module = _get_ptx_module()
        module.launch(
            "sigmoid_forward",
            grid=(grid_x, 1, 1),
            block=(threads, 1, 1),
            arguments=[x, out, i32(n)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

